<?php include 'config.php'; require_user(); $uid=(int)$_SESSION['user_id']; $r=get_resume($conn,$uid)?:[]; $cl=[];$q=$conn->prepare('SELECT * FROM cover_letters WHERE user_id=? LIMIT 1');if($q){$q->bind_param('i',$uid);$q->execute();$cl=$q->get_result()->fetch_assoc()?:[];} $msg=''; if(isset($_POST['save_cover'])){$data=['recipient'=>trim($_POST['recipient']??''),'company'=>trim($_POST['company']??''),'role'=>trim($_POST['role']??''),'opening'=>trim($_POST['opening']??''),'body'=>trim($_POST['body']??''),'closing'=>trim($_POST['closing']??'')];$q=$conn->prepare('INSERT INTO cover_letters(user_id,recipient,company,role,opening,body,closing) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE recipient=VALUES(recipient),company=VALUES(company),role=VALUES(role),opening=VALUES(opening),body=VALUES(body),closing=VALUES(closing)');$q->bind_param('issssss',$uid,$data['recipient'],$data['company'],$data['role'],$data['opening'],$data['body'],$data['closing']);$q->execute();$cl=$data;$msg='Cover letter saved.';} include 'includes_site.php'; site_header('Cover Letter Builder','template'); ?>
<main class="public-page"><section class="public-hero"><div><span class="eyebrow">COVER LETTER BUILDER</span><h1>Match your letter to your resume.</h1><p>Write a concise, role-specific letter using your saved career information.</p></div></section><?php if($msg): ?><div class="saved">✓ <?=e($msg)?></div><?php endif; ?><div class="split-tool"><section class="public-card form-card" style="max-width:none"><form method="post"><div class="field-grid"><label>Recipient<input name="recipient" value="<?=e($cl['recipient']??'')?>" placeholder="Hiring Manager"></label><label>Company<input name="company" value="<?=e($cl['company']??'')?>" placeholder="Company name"></label><label>Target role<input name="role" value="<?=e($cl['role']??($r['target_job']??''))?>"></label><label>Opening<input name="opening" value="<?=e($cl['opening']??'')?>" placeholder="Why this role interests you"></label><label class="full-field">Main body<textarea name="body" rows="10" placeholder="Connect your strongest experience to the role."><?=e($cl['body']??'')?></textarea></label><label class="full-field">Closing<textarea name="closing" rows="4" placeholder="Thank the reader and invite the next step."><?=e($cl['closing']??'')?></textarea></label></div><button class="primary" name="save_cover">Save cover letter →</button></form></section><section class="tool-preview cover-letter-preview"><h2><?=e($r['full_name']??$_SESSION['user_name']??'Your Name')?></h2><p><?=e($cl['recipient']??'Hiring Manager')?><br><?=e($cl['company']??'Company')?></p><p><?=e($cl['opening']??'Your opening will appear here.')?></p><p><?=e($cl['body']??'Your main body will appear here.')?></p><p><?=e($cl['closing']??'Thank you for your consideration.')?></p></section></div></main>
